{
  "regions": [
    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "यदा किञ्चित्किञ्चिद्बुधजनसकाशादवगतं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तदा मूर्खोस्मीति ज्वर इव मदो मे व्यपगतः ॥ ३१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "निर्ममतास्वरूपमाह ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अतिक्रान्तः कालो लटभललनाभोगसुलभो",
          "end": "line"
        },
        {
          "n": 2,
          "text": "भ्रमन्तः श्रान्ताः स्मः सुचिरमिह संसारसरणौ ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "इदानीं स्वःसिन्धोस्तटभुवि समाक्रन्दनगिरः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "सुतारैः फूत्कारैः शिव शिव शिवेति प्रतनुमः ॥ ३२ ॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "माने म्लायिनि खण्डिते च वसुनि व्यर्थं प्रयातेर्थिनि",
          "end": "line"
        },
        {
          "n": 2,
          "text": "क्षीणे बन्धुजने गते परिजने नष्टे शनैर्यौवने ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "युक्तं केवलमेतदेव सुधियां यज्जह्नुकन्यापयः-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "पूतग्रावगिरीन्द्रकन्दरदरीकुञ्जे निवासः क्वचित् ॥ ३३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "परेषां चेतांसि प्रतिदिवसमाराध्य बहु हा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "प्रसादं किं नेतुं विशसि हृदय क्लेशकलितम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "line"
        },
        {
          "n": 4,
          "text": "प्रसन्ने त्वय्यन्तः स्वयमुदितचिन्तामणिगुणे",
          "end": "line"
        },
        {
          "n": 5,
          "text": "विमुक्तः संकल्पः किमभिलषितं पुष्यति न ते ॥ ३४ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "XXXI. See Nîtis'ataka St. 8.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
